package android.content; import android.net.Uri; import java.util.*; public class Intent {public static final int FLAG_ACTIVITY_CLEAR_TOP=1,FLAG_ACTIVITY_SINGLE_TOP=2; public String action;public Uri data;public int flags;private final Map<String,Object> extras=new HashMap<>();public Intent(){}public Intent(Context c,Class<?> klass){}public Intent setAction(String a){action=a;return this;}public String getAction(){return action;}public Intent putExtra(String k,int v){extras.put(k,v);return this;}public Intent putExtra(String k,long v){extras.put(k,v);return this;}public Intent putExtra(String k,String v){extras.put(k,v);return this;}public int getIntExtra(String k,int def){Object o=extras.get(k);return o instanceof Integer?(Integer)o:def;}public long getLongExtra(String k,long def){Object o=extras.get(k);return o instanceof Long?(Long)o:def;}public String getStringExtra(String k){return (String)extras.get(k);}public Intent addFlags(int f){flags|=f;return this;}public Intent setData(Uri u){data=u;return this;} }